contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint seed) public payable {
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        assert(!initReverted);
    }

    receive() external payable {}
}

